-- secours-degat-des-eaux-conflit-acces — L'occupant du dessus refuse d'ouvrir malgré l'inondation
SELECT public.fn_cp_import_case('secours-degat-des-eaux-conflit-acces', '{"slug": "secours-degat-des-eaux-conflit-acces", "title": "L''occupant du dessus refuse d''ouvrir malgré l''inondation", "theme_slug": "police-secours", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 21 heures. Vous êtes engagés dans une copropriété où Mme ARNAUD, locataire de l''appartement du dessous, signale une inondation en provenance de l''appartement du dessus, l''eau s''infiltrant visiblement à travers son plafond et endommageant son mobilier. Elle a sonné plusieurs fois chez le voisin du dessus sans réponse, bien qu''elle entende de la musique et des voix à l''intérieur.\n\nÀ votre arrivée, vous confirmez l''écoulement d''eau et sonnez à votre tour, sans obtenir de réponse malgré des bruits de vie manifestes à l''intérieur du logement concerné. Aucune vie n''est en danger, aucune urgence vitale ne semble caractérisée, il s''agit d''un dommage purement matériel qui continue cependant de s''aggraver au fil des minutes.\n\nMme ARNAUD, de plus en plus excédée, vous demande d''enfoncer la porte pour faire cesser l''inondation le plus rapidement possible.", "questions": [{"position": 1, "max_points": 5, "label": "Forcez-vous l''accès au logement du voisin pour faire cesser ce dégât des eaux ?", "hint": "L''urgence matérielle, même réelle, ne se confond pas avec l''urgence vitale qui seule justifie certaines mesures exceptionnelles.", "perfect": "Je ne force pas l''accès au logement sur la seule base de ce dommage matériel, aussi réel et gênant soit-il, l''absence de danger vital caractérisé ne justifiant pas une mesure aussi exceptionnelle qu''une entrée forcée dans un domicile.\n\nJe reconnais les limites de mes pouvoirs face à un dommage purement matériel qui continue de s''aggraver, cette situation relevant davantage de procédures civiles et d''intervention de professionnels spécialisés que d''une action policière d''urgence.\n\nJe ne me laisse pas influencer par l''insistance légitime mais compréhensible de Mme ARNAUD, qui souhaite naturellement voir cesser au plus vite le dommage qu''elle subit, sans que cela change le cadre juridique applicable à mon intervention.\n\nJe continue cependant à tenter de joindre l''occupant du dessus par d''autres moyens avant de considérer la situation comme définitivement bloquée, sans pour autant recourir à la force.", "points": [{"position": 1, "label": "Ne pas forcer l''accès sur la seule base du dommage matériel", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : l''absence de danger vital ne justifie pas une entrée forcée.", "groups": [{"position": 1, "keywords": ["ne pas forcer l''accès", "dommage matériel", "pas de danger vital"]}]}, {"position": 2, "label": "Reconnaître les limites des pouvoirs policiers face à un dommage purement matériel", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Situation relevant de procédures civiles plutôt que d''une action d''urgence policière.", "groups": [{"position": 1, "keywords": ["limites des pouvoirs", "dommage purement matériel", "procédures civiles"]}]}, {"position": 3, "label": "Ne pas se laisser influencer par l''insistance de la plaignante", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Le cadre juridique applicable ne change pas malgré l''insistance légitime.", "groups": [{"position": 1, "keywords": ["ne pas se laisser influencer", "insistance légitime", "cadre juridique inchangé"]}]}, {"position": 4, "label": "Continuer à tenter de joindre l''occupant par d''autres moyens sans recourir à la force", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Explorer les alternatives avant de considérer la situation bloquée.", "groups": [{"position": 1, "keywords": ["tenter de joindre autrement", "sans recourir à la force", "alternatives"]}]}]}, {"position": 2, "max_points": 5, "label": "Quelles alternatives concrètes proposez-vous à Mme ARNAUD pour limiter les dégâts en attendant une résolution ?", "hint": "L''impossibilité d''agir sur la cause ne dispense pas d''orienter vers des solutions pratiques immédiates.", "perfect": "Je l''oriente vers la coupure de l''alimentation en eau générale de l''immeuble si elle en a la possibilité ou si le gardien ou le syndic peut être contacté rapidement, ce qui pourrait limiter l''aggravation du dégât en attendant une résolution plus durable.\n\nJe lui conseille de documenter précisément l''étendue des dégâts par des photographies, ce qui lui sera utile pour ses démarches auprès de son assurance, indépendamment de la question de l''accès au logement du dessus.\n\nJe l''informe de la possibilité de contacter le syndic de copropriété ou le propriétaire du logement concerné, qui pourrait disposer de moyens légaux d''accès que je n''ai pas moi-même dans ce contexte purement matériel.\n\nJe reste disponible pour constater les faits et rédiger un rapport de mon passage, ce qui pourra appuyer ses démarches ultérieures sans que cela ne nécessite une intervention forcée de ma part.", "points": [{"position": 1, "label": "Orienter vers la coupure de l''alimentation en eau générale si possible", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Limiter l''aggravation en attendant une résolution plus durable.", "groups": [{"position": 1, "keywords": ["coupure d''eau générale", "limiter l''aggravation", "gardien ou syndic"]}]}, {"position": 2, "label": "Conseiller de documenter les dégâts par photographies pour l''assurance", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Utile pour les démarches assurance indépendamment de l''accès au logement.", "groups": [{"position": 1, "keywords": ["documenter les dégâts", "photographies", "assurance"]}]}, {"position": 3, "label": "Informer de la possibilité de contacter le syndic ou le propriétaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Moyens légaux d''accès que la police n''a pas dans ce contexte matériel.", "groups": [{"position": 1, "keywords": ["contacter le syndic", "propriétaire", "moyens légaux d''accès"]}]}, {"position": 4, "label": "Rester disponible pour constater les faits et rédiger un rapport", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Appuyer ses démarches ultérieures sans intervention forcée.", "groups": [{"position": 1, "keywords": ["constater les faits", "rapport", "démarches ultérieures"]}]}]}, {"position": 3, "max_points": 5, "label": "L''occupant du dessus finit par ouvrir, visiblement gêné, expliquant avoir simplement mal entendu à cause de la musique. Comment gérez-vous cette conclusion ?", "hint": "Une explication plausible ne dispense pas de vérifier que le problème est effectivement réglé avant de partir.", "perfect": "Je vérifie que l''origine de la fuite est effectivement traitée ou en passe de l''être, sans me contenter de son explication orale sans constat concret de la résolution du problème matériel.\n\nJe ne me positionne pas comme juge de la sincérité de son explication sur le fait de ne pas avoir entendu les sollicitations, cette question relevant davantage d''un désaccord entre voisins que d''une infraction que j''aurais à qualifier.\n\nJe m''assure que les deux parties peuvent désormais échanger directement sur la suite à donner, notamment la prise en charge des dégâts constatés, sans que mon rôle s''étende à la médiation complète de leur différend matériel.\n\nJe consigne cette intervention avec précision, y compris le fait que l''accès a finalement pu être obtenu sans recourir à la force, ce qui confirme la pertinence d''avoir attendu plutôt que d''avoir forcé l''entrée.", "points": [{"position": 1, "label": "Vérifier que l''origine de la fuite est effectivement traitée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ne pas se contenter de l''explication orale sans constat concret.", "groups": [{"position": 1, "keywords": ["vérifier la résolution", "constat concret", "pas seulement l''explication orale"]}]}, {"position": 2, "label": "Ne pas juger la sincérité de son explication sur la non-réponse", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Relève d''un désaccord entre voisins plutôt que d''une infraction à qualifier.", "groups": [{"position": 1, "keywords": ["ne pas juger la sincérité", "désaccord de voisins", "pas une infraction"]}]}, {"position": 3, "label": "Permettre aux deux parties d''échanger directement sans s''étendre en médiateur complet", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rôle limité, pas une médiation complète du différend matériel.", "groups": [{"position": 1, "keywords": ["échanger directement", "pas de médiation complète", "rôle limité"]}]}, {"position": 4, "label": "Consigner l''intervention en confirmant la pertinence d''avoir attendu plutôt que forcé", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "L''accès obtenu sans force confirme la bonne décision initiale.", "groups": [{"position": 1, "keywords": ["consigner", "pertinence d''avoir attendu", "sans avoir forcé"]}]}]}]}'::jsonb);

-- secours-alerte-personne-disparue-zone-rurale — Il est parti marcher à 14 h, la nuit tombe dans une heure
SELECT public.fn_cp_import_case('secours-alerte-personne-disparue-zone-rurale', '{"slug": "secours-alerte-personne-disparue-zone-rurale", "title": "Il est parti marcher à 14 h, la nuit tombe dans une heure", "theme_slug": "police-secours", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 19 heures, en plein hiver. Vous êtes engagés suite à un signalement de disparition inquiétante concernant M. ROUSSEAU, 71 ans, parti marcher seul dans une zone boisée et vallonnée vers 14 heures, sans être rentré depuis. Sa femme, très inquiète, précise qu''il connaît bien ces chemins mais qu''il prend un traitement pour le cœur qu''il n''a pas emporté avec lui.\n\nLa nuit va tomber dans environ une heure, et la zone à couvrir est vaste, avec de nombreux chemins possibles et un terrain accidenté rendant la progression difficile dans l''obscurité. La température chute déjà sensiblement, et le risque d''hypothermie s''ajoute à l''inquiétude concernant son état cardiaque en l''absence de son traitement.\n\nVous disposez d''effectifs limités dans l''immédiat, des renforts supplémentaires ayant été demandés mais leur délai d''arrivée restant incertain compte tenu de l''éloignement du secteur rural concerné.", "questions": [{"position": 1, "max_points": 5, "label": "Comment organisez-vous la recherche compte tenu de la fenêtre de temps qui se referme rapidement ?", "hint": "Chaque minute perdue avant la nuit réduit drastiquement l''efficacité de toute recherche ultérieure.", "perfect": "J''engage la recherche sans délai, la fenêtre d''une heure avant la tombée de la nuit étant précieuse et ne devant pas être perdue en tergiversations ou en attente des renforts avant de commencer quoi que ce soit.\n\nJe priorise la zone de recherche en fonction des informations disponibles sur ses habitudes de marche et les chemins qu''il emprunte habituellement, plutôt que de chercher à ratisser l''ensemble de la zone boisée de manière non ciblée et donc inefficace.\n\nJe sollicite l''aide de la femme de M. ROUSSEAU pour préciser au maximum ces habitudes et itinéraires probables, cette connaissance fine du terrain par un proche étant précieuse pour orienter efficacement les recherches dans le temps limité disponible.\n\nJe communique clairement l''urgence de la situation, notamment le risque cardiaque et le risque d''hypothermie combinés, pour obtenir la mobilisation la plus rapide possible des renforts et moyens complémentaires disponibles.", "points": [{"position": 1, "label": "Engager la recherche sans délai plutôt que d''attendre les renforts", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : organiser et prioriser la zone de recherche sans attendre.", "groups": [{"position": 1, "keywords": ["engager sans délai", "ne pas attendre les renforts", "fenêtre précieuse"]}]}, {"position": 2, "label": "Prioriser la zone selon les habitudes de marche connues", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Recherche ciblée plutôt qu''un ratissage non ciblé et inefficace.", "groups": [{"position": 1, "keywords": ["prioriser la zone", "habitudes connues", "recherche ciblée"]}]}, {"position": 3, "label": "Solliciter la femme pour préciser les itinéraires probables", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Connaissance fine du terrain par un proche précieuse pour orienter.", "groups": [{"position": 1, "keywords": ["solliciter la femme", "itinéraires probables", "connaissance du terrain"]}]}, {"position": 4, "label": "Communiquer clairement l''urgence combinée (cardiaque et hypothermie) pour mobiliser des renforts", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Obtenir la mobilisation la plus rapide possible des moyens complémentaires.", "groups": [{"position": 1, "keywords": ["communiquer l''urgence", "mobiliser des renforts", "risque combiné"]}]}]}, {"position": 2, "max_points": 5, "label": "La nuit tombe et aucune trace de M. ROUSSEAU n''a été trouvée. Comment adaptez-vous la suite des recherches avec ces effectifs limités ?", "hint": "La tombée de la nuit change radicalement les moyens et méthodes nécessaires, sans pour autant justifier un arrêt des recherches.", "perfect": "Je ne considère à aucun moment l''idée d''interrompre les recherches à la tombée de la nuit, le risque vital pour M. ROUSSEAU restant entier voire s''aggravant avec la baisse des températures et l''absence de son traitement cardiaque.\n\nJe sollicite les moyens spécialisés adaptés à une recherche nocturne en milieu rural, comme des équipes cynophiles ou des moyens de vision nocturne, ces outils devenant indispensables une fois l''obscurité tombée sur un terrain aussi accidenté.\n\nJe réorganise la répartition de mes effectifs limités en tenant compte des contraintes nouvelles de sécurité que représente une progression nocturne sur un terrain vallonné et boisé, sans exposer inutilement mes collègues à des risques de chute ou d''égarement.\n\nJe maintiens une communication constante avec l''ensemble des effectifs engagés dans la recherche, ce qui devient encore plus critique dans l''obscurité pour éviter tout isolement ou perte de coordination entre les différents groupes de recherche.", "points": [{"position": 1, "label": "Ne pas envisager d''interrompre les recherches à la tombée de la nuit", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Le risque vital reste entier voire s''aggrave avec l''obscurité et le froid.", "groups": [{"position": 1, "keywords": ["ne pas interrompre", "risque vital entier", "malgré la nuit"]}]}, {"position": 2, "label": "Solliciter des moyens spécialisés adaptés à la recherche nocturne", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Équipes cynophiles ou vision nocturne indispensables dans l''obscurité.", "groups": [{"position": 1, "keywords": ["moyens spécialisés", "recherche nocturne", "cynophile ou vision nocturne"]}]}, {"position": 3, "label": "Réorganiser les effectifs en tenant compte des contraintes de sécurité nocturnes", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ne pas exposer les collègues à des risques inutiles sur terrain accidenté.", "groups": [{"position": 1, "keywords": ["réorganiser les effectifs", "sécurité nocturne", "terrain accidenté"]}]}, {"position": 4, "label": "Maintenir une communication constante entre les groupes de recherche", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Éviter tout isolement ou perte de coordination dans l''obscurité.", "groups": [{"position": 1, "keywords": ["communication constante", "éviter l''isolement", "coordination"]}]}]}, {"position": 3, "max_points": 5, "label": "M. ROUSSEAU est finalement retrouvé, désorienté mais vivant, après plusieurs heures de recherche. Comment gérez-vous les derniers instants avant la prise en charge médicale ?", "hint": "Le moment de la découverte reste critique et appelle une méthode précise, pas un simple soulagement.", "perfect": "Je le rassure immédiatement par la parole en évitant de le brusquer, sa désorientation pouvant le rendre confus sur ce qui se passe après plusieurs heures d''égarement dans le froid.\n\nJe déclenche sans délai l''alerte aux secours médicaux si ce n''est pas déjà fait, son absence de traitement cardiaque depuis plusieurs heures et son exposition prolongée au froid constituant des facteurs de risque sérieux nécessitant une évaluation rapide.\n\nJe ne le fais pas marcher inutilement s''il présente des signes de faiblesse, en privilégiant son immobilisation et sa protection contre le froid en attendant l''arrivée des moyens médicaux appropriés à son évacuation.\n\nJe communique rapidement la bonne nouvelle de cette découverte à son épouse et à l''ensemble des effectifs engagés dans la recherche, ce qui permet de mettre fin à la mobilisation généralisée dans les meilleurs délais.", "points": [{"position": 1, "label": "Le rassurer immédiatement sans le brusquer malgré sa désorientation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Confusion possible après plusieurs heures d''égarement dans le froid.", "groups": [{"position": 1, "keywords": ["rassurer immédiatement", "sans brusquer", "désorientation"]}]}, {"position": 2, "label": "Déclencher sans délai l''alerte aux secours médicaux", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Absence de traitement et exposition prolongée constituant des facteurs de risque sérieux.", "groups": [{"position": 1, "keywords": ["alerte aux secours médicaux", "sans délai", "facteurs de risque"]}]}, {"position": 3, "label": "Privilégier son immobilisation et sa protection contre le froid", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ne pas le faire marcher inutilement s''il présente des signes de faiblesse.", "groups": [{"position": 1, "keywords": ["immobilisation", "protection contre le froid", "pas de marche inutile"]}]}, {"position": 4, "label": "Communiquer rapidement la découverte pour mettre fin à la mobilisation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Informer l''épouse et les effectifs engagés dans les meilleurs délais.", "groups": [{"position": 1, "keywords": ["communiquer rapidement", "mettre fin à la mobilisation", "épouse et effectifs"]}]}]}]}'::jsonb);

-- secours-conflit-avec-service-partenaire — Les pompiers veulent transporter, la famille s'y oppose physiquement
SELECT public.fn_cp_import_case('secours-conflit-avec-service-partenaire', '{"slug": "secours-conflit-avec-service-partenaire", "title": "Les pompiers veulent transporter, la famille s''y oppose physiquement", "theme_slug": "police-secours", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 2 heures. Vous êtes appelés en renfort des pompiers déjà présents au domicile d''un homme âgé ayant fait un malaise, ces derniers jugeant nécessaire un transport hospitalier immédiat compte tenu des symptômes constatés. La famille présente, composée du fils et de la belle-fille de la victime, s''oppose physiquement à ce transport, estimant que leur père « refuse toujours d''aller à l''hôpital » et qu''il faut respecter sa volonté.\n\nLes pompiers, gênés dans leur intervention par cette opposition physique, vous sollicitent pour pouvoir mener à bien leur mission de secours. La victime elle-même, semi-consciente, ne peut pas exprimer clairement sa propre volonté dans l''état où elle se trouve actuellement.\n\nLe fils, très agité, se place physiquement entre les pompiers et son père, répétant qu''il « connaît son père mieux que quiconque » et qu''on ne l''emmènera pas contre sa volonté supposée.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre priorité immédiate face à cette opposition physique qui entrave l''intervention des pompiers ?", "hint": "Votre rôle ici est de protéger un service partenaire dans l''exercice de sa mission de secours, pas d''arbitrer le fond du désaccord familial.", "perfect": "Ma priorité immédiate est de protéger les pompiers dans l''exercice de leur mission de secours, cette opposition physique constituant une entrave à une intervention médicale urgente qui doit cesser sans délai.\n\nJe ne me positionne pas comme arbitre de la volonté supposée de la victime, celle-ci étant actuellement semi-consciente et donc dans l''incapacité d''exprimer clairement son consentement ou son refus à cet instant précis.\n\nJe considère que l''appréciation de la nécessité du transport relève de la compétence exclusive des pompiers présents sur place, mon rôle se limitant à garantir qu''ils puissent exercer cette compétence sans entrave physique de la famille.\n\nJe m''adresse fermement mais avec humanité au fils, en reconnaissant sa préoccupation légitime pour la volonté de son père tout en lui expliquant clairement que l''urgence médicale constatée par les professionnels doit primer à ce stade.", "points": [{"position": 1, "label": "Protéger les pompiers dans l''exercice de leur mission de secours", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : protéger les intervenants et rétablir les conditions du soin.", "groups": [{"position": 1, "keywords": ["protéger les pompiers", "mission de secours", "entrave à faire cesser"]}]}, {"position": 2, "label": "Ne pas se positionner comme arbitre de la volonté supposée de la victime", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Victime semi-consciente, incapable d''exprimer clairement son consentement.", "groups": [{"position": 1, "keywords": ["ne pas arbitrer", "volonté supposée", "semi-consciente"]}]}, {"position": 3, "label": "Considérer que l''appréciation de la nécessité du transport relève des pompiers", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Compétence exclusive des professionnels de santé présents.", "groups": [{"position": 1, "keywords": ["compétence des pompiers", "nécessité du transport", "rôle de garantir sans entrave"]}]}, {"position": 4, "label": "S''adresser fermement mais avec humanité au fils", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Reconnaître sa préoccupation tout en expliquant la priorité de l''urgence médicale.", "groups": [{"position": 1, "keywords": ["fermement avec humanité", "reconnaître la préoccupation", "priorité de l''urgence"]}]}]}, {"position": 2, "max_points": 5, "label": "Le fils continue de faire physiquement barrage malgré vos explications. Jusqu''où allez-vous dans la fermeté pour rétablir les conditions du soin ?", "hint": "La fermeté nécessaire doit rester proportionnée à ce qui est strictement nécessaire pour permettre l''intervention des secours.", "perfect": "J''engage une fermeté progressive et proportionnée, en commençant par des sommations claires avant d''envisager toute mesure de contrainte physique, cette progression respectant le principe de proportionnalité applicable à toute intervention de ce type.\n\nJe ne recours à la contrainte physique qu''en dernier recours, si les explications et la fermeté verbale ne suffisent pas à faire cesser cette entrave à l''intervention des pompiers qui reste indispensable pour la santé de la victime.\n\nJe reste concentrée sur l''objectif précis de permettre le transport de la victime, sans transformer cette intervention en un conflit disproportionné avec le fils qui dépasserait ce qui est strictement nécessaire.\n\nJe reste attentive à ce que mon intervention ne retarde pas davantage la prise en charge de la victime, chaque minute supplémentaire d''opposition pouvant aggraver son état déjà préoccupant selon l''évaluation des pompiers.", "points": [{"position": 1, "label": "Engager une fermeté progressive et proportionnée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Sommations claires avant toute contrainte physique, principe de proportionnalité.", "groups": [{"position": 1, "keywords": ["fermeté progressive", "proportionnée", "sommations avant contrainte"]}]}, {"position": 2, "label": "Ne recourir à la contrainte physique qu''en dernier recours", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Si la fermeté verbale ne suffit pas à faire cesser l''entrave.", "groups": [{"position": 1, "keywords": ["dernier recours", "contrainte physique", "si insuffisant"]}]}, {"position": 3, "label": "Rester concentrée sur l''objectif de permettre le transport sans disproportion", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ne pas transformer l''intervention en conflit disproportionné.", "groups": [{"position": 1, "keywords": ["objectif précis", "sans disproportion", "pas de conflit disproportionné"]}]}, {"position": 4, "label": "Ne pas retarder davantage la prise en charge de la victime", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Chaque minute supplémentaire peut aggraver l''état déjà préoccupant.", "groups": [{"position": 1, "keywords": ["ne pas retarder", "aggraver l''état", "minute supplémentaire"]}]}]}, {"position": 3, "max_points": 5, "label": "Une fois le transport effectué, comment accompagnez-vous la famille sur le plan humain après cette confrontation ?", "hint": "La tension du moment ne doit pas faire oublier que cette famille reste inquiète pour un proche qu''elle aime.", "perfect": "Je reconnais que le fils agissait par inquiétude et par attachement envers son père, malgré la méthode inappropriée qu''il a employée en s''opposant physiquement aux secours, sans pour autant excuser ce comportement qui devait cesser.\n\nJe lui explique posément, une fois la tension retombée, que cette opposition physique aurait pu avoir des conséquences graves si elle avait retardé davantage une prise en charge nécessaire, dans un esprit pédagogique plutôt que punitif.\n\nJe lui donne des informations pratiques sur l''hôpital où son père a été transporté, ce qui répond concrètement à son inquiétude légitime tout en clôturant cette intervention de manière constructive.\n\nJe consigne cet incident avec précision, notamment l''opposition physique constatée, ce qui pourra être utile pour la suite si une qualification pénale devait être envisagée pour cette entrave à l''intervention des secours.", "points": [{"position": 1, "label": "Reconnaître l''inquiétude et l''attachement du fils sans excuser le comportement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Comprendre le motif sans en faire une justification.", "groups": [{"position": 1, "keywords": ["reconnaître l''inquiétude", "sans excuser", "attachement au père"]}]}, {"position": 2, "label": "Expliquer posément les conséquences possibles de son opposition, dans un esprit pédagogique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Pédagogique plutôt que punitif une fois la tension retombée.", "groups": [{"position": 1, "keywords": ["expliquer posément", "esprit pédagogique", "conséquences possibles"]}]}, {"position": 3, "label": "Donner des informations pratiques sur l''hôpital de destination", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Répondre concrètement à l''inquiétude légitime de la famille.", "groups": [{"position": 1, "keywords": ["informations sur l''hôpital", "répondre à l''inquiétude", "concrètement"]}]}, {"position": 4, "label": "Consigner précisément l''opposition physique constatée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Utile pour une éventuelle qualification pénale de l''entrave.", "groups": [{"position": 1, "keywords": ["consigner précisément", "qualification pénale possible", "entrave aux secours"]}]}]}]}'::jsonb);

-- secours-personne-victime-malaise-lieu-culte — Une centaine de fidèles, un homme s'effondre au fond
SELECT public.fn_cp_import_case('secours-personne-victime-malaise-lieu-culte', '{"slug": "secours-personne-victime-malaise-lieu-culte", "title": "Une centaine de fidèles, un homme s''effondre au fond", "theme_slug": "police-secours", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 11 h 30. Vous êtes engagés dans un lieu de culte en pleine cérémonie religieuse rassemblant une centaine de fidèles, suite au signalement d''un homme d''une soixantaine d''années qui s''est effondré au fond de la salle, apparemment victime d''un malaise. La cérémonie continue de se dérouler, certains fidèles n''ayant même pas remarqué l''incident au fond de la salle.\n\nQuelques personnes proches de la victime commencent à s''agiter, créant un début de mouvement dans l''assistance, tandis que l''officiant, poursuivant la cérémonie, ne semble pas avoir été informé de la situation. L''homme reste inconscient au sol, sa respiration semblant faible mais présente.\n\nVous devez intervenir efficacement tout en tenant compte de la sensibilité particulière de ce lieu et du moment précis de la cérémonie en cours.", "questions": [{"position": 1, "max_points": 5, "label": "Comment intervenez-vous auprès de la victime tout en respectant le cadre du lieu et de la cérémonie en cours ?", "hint": "L''urgence médicale prime, mais la manière de l''exercer peut respecter ou heurter inutilement le cadre du lieu.", "perfect": "J''interviens sans délai auprès de la victime pour réaliser un bilan de son état, l''urgence médicale primant sur toute autre considération, y compris le déroulement de la cérémonie en cours.\n\nJe m''efforce cependant de le faire avec la plus grande discrétion possible compte tenu du lieu, en évitant par exemple de crier des instructions qui perturberaient inutilement l''ensemble de l''assemblée au-delà de ce qui est nécessaire pour porter secours efficacement.\n\nJe sollicite si possible l''aide discrète d''une personne proche de la victime ou d''un responsable du lieu pour m''assister, plutôt que de créer moi-même une agitation supplémentaire en multipliant les déplacements dans la salle.\n\nJe reste concentrée sur les gestes de premiers secours nécessaires, sans me laisser distraire par le contexte cérémoniel qui, bien que particulier, ne doit pas retarder ma prise en charge de l''urgence vitale potentielle.", "points": [{"position": 1, "label": "Intervenir sans délai pour réaliser un bilan, l''urgence primant sur la cérémonie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : intervenir efficacement en respectant le cadre du lieu.", "groups": [{"position": 1, "keywords": ["intervenir sans délai", "bilan de l''état", "urgence prime"]}]}, {"position": 2, "label": "Agir avec discrétion pour ne pas perturber inutilement l''assemblée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter de crier ou de perturber au-delà du nécessaire.", "groups": [{"position": 1, "keywords": ["discrétion", "ne pas perturber", "au-delà du nécessaire"]}]}, {"position": 3, "label": "Solliciter l''aide discrète d''un proche ou d''un responsable du lieu", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter de créer une agitation supplémentaire par soi-même.", "groups": [{"position": 1, "keywords": ["aide discrète", "responsable du lieu", "éviter l''agitation"]}]}, {"position": 4, "label": "Rester concentré sur les gestes de secours sans se laisser distraire par le contexte", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Le contexte cérémoniel ne doit pas retarder la prise en charge de l''urgence.", "groups": [{"position": 1, "keywords": ["concentré sur les gestes", "ne pas retarder", "contexte cérémoniel"]}]}]}, {"position": 2, "max_points": 5, "label": "L''officiant poursuit la cérémonie sans être informé. Comment gérez-vous cette information à transmettre sans créer de perturbation excessive ?", "hint": "Informer l''officiant est nécessaire, mais la manière de le faire compte pour préserver la dignité du moment pour les autres fidèles.", "perfect": "Je fais discrètement passer l''information à l''officiant ou à un responsable du lieu, plutôt que de l''interpeller moi-même directement de manière visible devant l''ensemble de l''assemblée, ce qui créerait une perturbation excessive.\n\nJe laisse à l''officiant, une fois informé, le soin de décider de la meilleure façon de gérer la poursuite ou l''interruption de la cérémonie, cette décision relevant de sa responsabilité et de sa connaissance du cadre religieux plutôt que de la mienne.\n\nJe reste concentrée sur la prise en charge médicale de la victime pendant que cette information circule, sans laisser cet aspect organisationnel me détourner de l''urgence à traiter en priorité.\n\nJe respecte la décision qui sera prise concernant la cérémonie, qu''elle soit interrompue ou qu''elle se poursuive à distance de l''incident, cette question ne relevant pas de ma compétence à trancher moi-même.", "points": [{"position": 1, "label": "Faire discrètement passer l''information plutôt qu''interpeller visiblement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Éviter une perturbation excessive devant l''assemblée.", "groups": [{"position": 1, "keywords": ["discrètement", "pas d''interpellation visible", "éviter la perturbation"]}]}, {"position": 2, "label": "Laisser à l''officiant la décision sur la cérémonie", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Responsabilité relevant du cadre religieux, pas de la compétence policière.", "groups": [{"position": 1, "keywords": ["décision de l''officiant", "cadre religieux", "pas ma compétence"]}]}, {"position": 3, "label": "Rester concentrée sur la prise en charge médicale pendant la transmission", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ne pas se laisser détourner de l''urgence par l''aspect organisationnel.", "groups": [{"position": 1, "keywords": ["concentrée sur le médical", "ne pas se détourner", "urgence prioritaire"]}]}, {"position": 4, "label": "Respecter la décision prise concernant la poursuite de la cérémonie", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Question ne relevant pas de la compétence policière à trancher.", "groups": [{"position": 1, "keywords": ["respecter la décision", "pas à trancher", "cadre du lieu"]}]}]}, {"position": 3, "max_points": 5, "label": "Les secours médicaux arrivent et prennent en charge la victime. Comment gérez-vous la fin de cette intervention dans ce lieu particulier ?", "hint": "La fin de l''urgence médicale ne signifie pas nécessairement la fin de toute considération pour le lieu et les personnes présentes.", "perfect": "Je facilite l''évacuation de la victime par les secours médicaux de la manière la plus discrète possible, en tenant compte de la configuration du lieu pour minimiser la perturbation de l''assemblée toujours présente.\n\nJe remercie les personnes qui ont pu m''assister discrètement pendant l''intervention, notamment si un responsable du lieu ou un proche de la victime a facilité ma prise en charge dans ce contexte particulier.\n\nJe m''assure, avant de partir, qu''un proche de la victime pourra la rejoindre à l''hôpital si elle y est transportée, ce qui répond à une préoccupation humaine légitime au-delà de la seule gestion médicale immédiate.\n\nJe quitte les lieux sans prolonger inutilement ma présence une fois l''urgence traitée, respectant ainsi la reprise normale de la cérémonie ou des activités du lieu de culte.", "points": [{"position": 1, "label": "Faciliter une évacuation discrète minimisant la perturbation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Tenir compte de la configuration du lieu pour l''assemblée toujours présente.", "groups": [{"position": 1, "keywords": ["évacuation discrète", "minimiser la perturbation", "configuration du lieu"]}]}, {"position": 2, "label": "Remercier les personnes ayant assisté discrètement l''intervention", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaître l''aide apportée dans ce contexte particulier.", "groups": [{"position": 1, "keywords": ["remercier", "aide apportée", "contexte particulier"]}]}, {"position": 3, "label": "S''assurer qu''un proche pourra rejoindre la victime à l''hôpital", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Préoccupation humaine au-delà de la seule gestion médicale immédiate.", "groups": [{"position": 1, "keywords": ["proche à l''hôpital", "préoccupation humaine", "au-delà du médical"]}]}, {"position": 4, "label": "Quitter les lieux sans prolonger inutilement la présence", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Respecter la reprise normale des activités du lieu de culte.", "groups": [{"position": 1, "keywords": ["quitter sans prolonger", "reprise normale", "respecter le lieu"]}]}]}]}'::jsonb);

-- secours-vol-a-l-arrache-poursuite — L'auteur s'est engouffré dans les allées bondées
SELECT public.fn_cp_import_case('secours-vol-a-l-arrache-poursuite', '{"slug": "secours-vol-a-l-arrache-poursuite", "title": "L''auteur s''est engouffré dans les allées bondées", "theme_slug": "police-secours", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 10 h 45. Vous assistez, en patrouille pédestre dans un marché très fréquenté, à un vol à l''arrache : un individu vient d''arracher le collier d''une passante avant de s''enfuir en courant, s''engouffrant immédiatement dans les allées étroites et bondées du marché, bousculant plusieurs personnes sur son passage.\n\nVous engagez spontanément une poursuite, mais la densité de la foule dans les allées rend votre progression difficile, et vous constatez que continuer à courir à cette allure au milieu des étals et des clients pourrait provoquer des chutes ou des bousculades supplémentaires parmi les personnes présentes, notamment des personnes âgées et des enfants nombreux à cette heure de marché.\n\nL''auteur, plus agile dans son parcours de fuite qu''il semble avoir anticipé, prend de la distance à chaque virage dans les allées qu''il connaît visiblement mieux que vous.", "questions": [{"position": 1, "max_points": 5, "label": "Comment évaluez-vous la poursuite en cours au regard du risque qu''elle fait courir aux nombreux tiers présents ?", "hint": "Le succès potentiel d''une interpellation ne justifie pas n''importe quel niveau de risque pour les personnes présentes.", "perfect": "J''évalue en continu le risque que cette poursuite fait courir aux nombreux tiers présents dans ces allées bondées, en particulier aux personnes âgées et aux enfants qui pourraient être bousculés ou renversés par ma propre progression ou celle de l''auteur en fuite.\n\nJe reste consciente que la densité de la foule dans un marché constitue une circonstance très différente d''une poursuite en milieu dégagé, ce qui doit peser lourdement dans ma décision de continuer ou d''interrompre cette course-poursuite.\n\nJe n''hésite pas à renoncer à la poursuite si je constate qu''elle devient réellement dangereuse pour les tiers, un vol de collier, aussi condamnable soit-il, ne justifiant pas de mettre en danger des passants innocents pour tenter une interpellation dont le succès reste de toute façon incertain.\n\nJe garde à l''esprit que d''autres moyens d''identification et d''interpellation restent possibles a posteriori, ce qui relativise l''urgence absolue de maintenir cette poursuite à tout prix dans des conditions dangereuses.", "points": [{"position": 1, "label": "Évaluer en continu le risque pour les nombreux tiers présents", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : décision d''interrompre ou poursuivre en milieu saturé.", "groups": [{"position": 1, "keywords": ["évaluer le risque", "tiers présents", "milieu saturé"]}]}, {"position": 2, "label": "Considérer que la densité de foule change radicalement le contexte de la poursuite", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Différent d''une poursuite en milieu dégagé, à peser lourdement dans la décision.", "groups": [{"position": 1, "keywords": ["densité de la foule", "contexte différent", "peser dans la décision"]}]}, {"position": 3, "label": "Renoncer à la poursuite si elle devient dangereuse pour les tiers", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Un vol de collier ne justifie pas de mettre en danger des passants innocents.", "groups": [{"position": 1, "keywords": ["renoncer si dangereux", "ne pas mettre en danger", "passants innocents"]}]}, {"position": 4, "label": "Garder à l''esprit que d''autres moyens d''identification restent possibles a posteriori", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Relativise l''urgence de maintenir la poursuite à tout prix.", "groups": [{"position": 1, "keywords": ["moyens a posteriori", "relativiser l''urgence", "identification ultérieure"]}]}]}, {"position": 2, "max_points": 5, "label": "Vous décidez de renoncer à la poursuite directe. Que faites-vous concrètement à la place pour maximiser les chances d''identification ultérieure ?", "hint": "Renoncer à courir ne signifie pas renoncer à toute action utile.", "perfect": "Je communique immédiatement au centre d''information et de commandement une description aussi précise que possible de l''auteur et de sa direction de fuite au moment où je cesse ma propre poursuite, ce qui peut permettre à d''autres effectifs de prendre le relais dans de meilleures conditions.\n\nJe retourne rapidement vers la victime pour recueillir sa déclaration et une description complémentaire de l''auteur et des faits, ce contact direct avec elle étant immédiatement disponible et précieux pour la suite de l''enquête.\n\nJe vérifie si des commerçants du marché ou des systèmes de vidéoprotection présents aux abords pourraient avoir capté des images de la fuite, ce type de preuve pouvant s''avérer plus fiable qu''une poursuite interrompue en pleine foule.\n\nJe ne considère pas cet abandon de la poursuite comme un échec total, la sécurité des nombreux tiers ayant justifié ce choix, tout en restant actif sur les autres pistes d''identification disponibles.", "points": [{"position": 1, "label": "Communiquer immédiatement une description précise au centre de commandement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Permettre à d''autres effectifs de prendre le relais dans de meilleures conditions.", "groups": [{"position": 1, "keywords": ["communiquer la description", "centre de commandement", "prendre le relais"]}]}, {"position": 2, "label": "Retourner vers la victime pour recueillir sa déclaration", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Contact direct immédiatement disponible et précieux pour l''enquête.", "groups": [{"position": 1, "keywords": ["retourner vers la victime", "recueillir la déclaration", "contact précieux"]}]}, {"position": 3, "label": "Vérifier les éventuelles images de vidéoprotection ou témoignages de commerçants", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Preuve potentiellement plus fiable qu''une poursuite interrompue.", "groups": [{"position": 1, "keywords": ["vidéoprotection", "commerçants", "preuve fiable"]}]}, {"position": 4, "label": "Ne pas considérer l''abandon de la poursuite comme un échec total", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "La sécurité des tiers justifiait ce choix, rester actif sur d''autres pistes.", "groups": [{"position": 1, "keywords": ["pas un échec total", "sécurité justifiait le choix", "autres pistes actives"]}]}]}, {"position": 3, "max_points": 5, "label": "Un commerçant vous reproche de « ne pas avoir fait votre travail » en abandonnant la poursuite devant ses clients. Comment répondez-vous à cette critique ?", "hint": "Une critique publique sur une décision difficile mérite une explication posée plutôt qu''une justification défensive excessive.", "perfect": "Je ne me laisse pas déstabiliser par cette critique, en comprenant qu''elle part d''une incompréhension du contexte réel de ma décision plutôt que d''une évaluation informée de la situation à laquelle j''ai été confrontée.\n\nJe lui explique posément, sans excès de justification ni ton désagréable, que poursuivre dans cette foule dense aurait fait courir un risque réel à ses propres clients, ce qui aurait été disproportionné par rapport à l''objectif de rattraper l''auteur d''un vol.\n\nJe ne transforme pas cet échange en confrontation publique supplémentaire, en restant brève et factuelle dans ma réponse plutôt que de m''engager dans un débat prolongé devant les autres clients du marché.\n\nJe reste confiante dans le bien-fondé de ma décision, cette évaluation ayant été faite en temps réel avec les informations et contraintes dont je disposais à cet instant précis, indépendamment du jugement a posteriori de quelqu''un n''ayant pas vécu la situation.", "points": [{"position": 1, "label": "Ne pas se laisser déstabiliser par une critique fondée sur une incompréhension", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Comprendre que la critique ne tient pas compte du contexte réel.", "groups": [{"position": 1, "keywords": ["ne pas se laisser déstabiliser", "incompréhension du contexte", "critique non informée"]}]}, {"position": 2, "label": "Expliquer posément le risque réel qu''aurait fait courir la poursuite", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Sans excès de justification ni ton désagréable.", "groups": [{"position": 1, "keywords": ["expliquer posément", "risque réel", "sans excès de justification"]}]}, {"position": 3, "label": "Ne pas transformer l''échange en confrontation publique", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rester bref et factuel plutôt qu''un débat prolongé devant les clients.", "groups": [{"position": 1, "keywords": ["pas de confrontation publique", "bref et factuel", "sans débat prolongé"]}]}, {"position": 4, "label": "Rester confiante dans le bien-fondé de la décision prise en temps réel", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Évaluation faite avec les informations disponibles à cet instant précis.", "groups": [{"position": 1, "keywords": ["confiante dans la décision", "temps réel", "indépendamment du jugement a posteriori"]}]}]}]}'::jsonb);

-- secours-incident-train-en-marche — Le contrôleur signale un individu menaçant en voiture 4
SELECT public.fn_cp_import_case('secours-incident-train-en-marche', '{"slug": "secours-incident-train-en-marche", "title": "Le contrôleur signale un individu menaçant en voiture 4", "theme_slug": "police-secours", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 17 heures. Vous êtes présents à bord d''un train régional dans le cadre d''une mission de sécurisation, lorsque le contrôleur vous informe par radio qu''un individu en voiture 4, plusieurs wagons plus loin, tient des propos menaçants envers d''autres passagers et refuse de présenter son titre de transport, devenant de plus en plus agressif verbalement.\n\nLe train roule actuellement entre deux gares, la prochaine étant annoncée dans une dizaine de minutes. Vous ne disposez d''aucun renfort immédiatement mobilisable dans ce train, l''espace étant confiné et la possibilité de vous replier ou d''obtenir une aide extérieure étant nulle tant que le train est en mouvement.\n\nLe contrôleur vous demande s''il doit continuer à tenter de raisonner l''individu en attendant votre arrivée en voiture 4, ou s''il vaut mieux qu''il se tienne à distance en attendant votre intervention.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre recommandation immédiate au contrôleur avant même de vous déplacer vers la voiture 4 ?", "hint": "La sécurité du contrôleur, seul face à l''individu en attendant votre arrivée, est une préoccupation immédiate distincte de votre propre intervention à venir.", "perfect": "Je recommande immédiatement au contrôleur de ne pas s''exposer davantage et de se tenir à distance de l''individu en attendant mon arrivée, sa sécurité personnelle primant sur toute tentative de le raisonner seul face à une agressivité croissante.\n\nJe lui demande de continuer à observer la situation à distance et de me tenir informée de toute évolution pendant mon déplacement vers la voiture 4, cette information en temps réel restant précieuse pour préparer mon approche.\n\nJe me déplace sans délai vers la voiture 4 en informant si possible mon propre central de la situation, notamment de l''impossibilité d''obtenir un renfort immédiat compte tenu du train en mouvement.\n\nJe reste attentive à évaluer, en approchant, si d''autres passagers pourraient être directement menacés de manière imminente, ce qui influencerait la rapidité et la nature de mon intervention à mon arrivée sur place.", "points": [{"position": 1, "label": "Recommander au contrôleur de ne pas s''exposer davantage", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : sa sécurité prime sur une tentative de raisonner seul l''individu.", "groups": [{"position": 1, "keywords": ["ne pas s''exposer", "sécurité du contrôleur", "se tenir à distance"]}]}, {"position": 2, "label": "Demander au contrôleur de continuer à informer sur l''évolution de la situation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information en temps réel précieuse pour préparer l''approche.", "groups": [{"position": 1, "keywords": ["informer sur l''évolution", "temps réel", "préparer l''approche"]}]}, {"position": 3, "label": "Se déplacer sans délai en informant son propre central", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Signaler l''impossibilité de renfort immédiat compte tenu du train en mouvement.", "groups": [{"position": 1, "keywords": ["se déplacer sans délai", "informer le central", "train en mouvement"]}]}, {"position": 4, "label": "Évaluer en approchant si d''autres passagers sont directement menacés", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Influence la rapidité et la nature de l''intervention à l''arrivée.", "groups": [{"position": 1, "keywords": ["évaluer en approchant", "passagers menacés", "influence l''intervention"]}]}]}, {"position": 2, "max_points": 5, "label": "Une fois sur place face à l''individu agressif, comment adaptez-vous votre intervention compte tenu de l''espace confiné et mobile du train ?", "hint": "L''impossibilité de renfort immédiat et l''espace confiné imposent une approche différente d''une intervention en milieu ouvert.", "perfect": "Je privilégie une approche verbale de désescalade dans un premier temps, l''absence de renfort immédiat et l''espace confiné du wagon rendant toute intervention physique prématurée particulièrement risquée si elle devait mal tourner.\n\nJe reste consciente de l''impossibilité de repli ou d''aide extérieure tant que le train est en mouvement, ce qui m''incite à une gestion particulièrement prudente de la situation jusqu''à l''arrivée en gare.\n\nJe coordonne avec le contrôleur la possibilité d''une intervention facilitée à l''arrêt en gare plutôt qu''en pleine marche, notamment en envisageant de faire descendre les autres passagers de ce wagon à la prochaine gare pour limiter les tiers exposés.\n\nJe communique avec mon central pour qu''un renfort soit positionné à l''arrivée en gare, ce qui transforme cette intervention isolée en un dispositif coordonné dès que le train marquera son prochain arrêt.", "points": [{"position": 1, "label": "Privilégier une approche verbale de désescalade dans un premier temps", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : coordonner l''arrêt en gare plutôt qu''agir en marche.", "groups": [{"position": 1, "keywords": ["désescalade verbale", "intervention physique prématurée", "risquée sans renfort"]}]}, {"position": 2, "label": "Rester conscient de l''impossibilité de repli tant que le train roule", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Gestion particulièrement prudente jusqu''à l''arrivée en gare.", "groups": [{"position": 1, "keywords": ["impossibilité de repli", "train en mouvement", "gestion prudente"]}]}, {"position": 3, "label": "Coordonner avec le contrôleur une intervention facilitée à l''arrêt en gare", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Envisager de faire descendre les autres passagers pour limiter les tiers exposés.", "groups": [{"position": 1, "keywords": ["intervention à l''arrêt", "faire descendre les passagers", "limiter les tiers"]}]}, {"position": 4, "label": "Communiquer avec son central pour un renfort positionné à l''arrivée en gare", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transformer l''intervention isolée en dispositif coordonné.", "groups": [{"position": 1, "keywords": ["renfort en gare", "dispositif coordonné", "central informé"]}]}]}, {"position": 3, "max_points": 5, "label": "Le train arrive en gare et l''individu tente de descendre rapidement pour se fondre dans la foule du quai. Comment gérez-vous cet instant critique ?", "hint": "L''arrivée en gare, tout en apportant des renforts potentiels, crée aussi une opportunité de fuite qu''il faut anticiper.", "perfect": "J''anticipe cette tentative de fuite en position moi-même de manière à pouvoir intercepter l''individu dès la descente, plutôt que d''être prise au dépourvu par ce mouvement prévisible à l''arrêt en gare.\n\nJe communique si possible avec les renforts déjà positionnés sur le quai, s''ils ont pu être mis en place suite à ma communication antérieure, pour coordonner une interpellation qui ne mette pas en danger les autres usagers présents sur le quai.\n\nJe reste attentive à ne pas provoquer de mouvement de panique parmi les passagers descendant du train au même moment, une interpellation mal maîtrisée dans cette configuration pouvant créer une bousculade dangereuse.\n\nJe m''assure, une fois l''individu maîtrisé ou la situation stabilisée, que le contrôleur et les passagers témoins de l''incident initial puissent apporter leur témoignage pour la suite de la procédure.", "points": [{"position": 1, "label": "Anticiper la tentative de fuite en se positionnant pour intercepter", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Ne pas être pris au dépourvu par ce mouvement prévisible à l''arrêt.", "groups": [{"position": 1, "keywords": ["anticiper la fuite", "se positionner", "intercepter à la descente"]}]}, {"position": 2, "label": "Coordonner avec les renforts positionnés sur le quai si disponibles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Interpellation ne mettant pas en danger les autres usagers du quai.", "groups": [{"position": 1, "keywords": ["coordonner avec les renforts", "quai", "sans danger pour les usagers"]}]}, {"position": 3, "label": "Éviter de provoquer un mouvement de panique parmi les passagers descendants", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Une interpellation mal maîtrisée pourrait créer une bousculade dangereuse.", "groups": [{"position": 1, "keywords": ["éviter la panique", "sans bousculade", "descente simultanée"]}]}, {"position": 4, "label": "S''assurer que le contrôleur et les témoins puissent apporter leur témoignage", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Utile pour la suite de la procédure une fois la situation stabilisée.", "groups": [{"position": 1, "keywords": ["témoignage du contrôleur", "témoins", "suite de la procédure"]}]}]}]}'::jsonb);

-- secours-personne-agressive-hopital — Il menace le personnel et refuse de quitter la salle d'attente
SELECT public.fn_cp_import_case('secours-personne-agressive-hopital', '{"slug": "secours-personne-agressive-hopital", "title": "Il menace le personnel et refuse de quitter la salle d''attente", "theme_slug": "police-secours", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 1 heure. Vous êtes engagés aux urgences d''un hôpital où un homme d''une trentaine d''années, venu pour lui-même plus tôt dans la nuit, hausse le ton et menace verbalement le personnel soignant, leur reprochant un temps d''attente qu''il juge inacceptable. Il refuse de quitter la salle d''attente malgré les demandes répétées de l''équipe médicale, et son comportement devient de plus en plus imprévisible.\n\nLe personnel soignant vous informe qu''il présente par ailleurs des symptômes évoquant possiblement un état confusionnel ou une pathologie sous-jacente non encore diagnostiquée, ce qui pourrait expliquer en partie son agressivité inhabituelle et disproportionnée par rapport au motif invoqué.\n\nD''autres patients présents dans la salle d''attente, certains eux-mêmes fragiles ou souffrants, observent la scène avec inquiétude, sans qu''aucun contact physique n''ait pour l''instant été exercé par l''homme envers quiconque.", "questions": [{"position": 1, "max_points": 5, "label": "Comment qualifiez-vous cette situation avant de décider de votre mode d''intervention ?", "hint": "Une agressivité peut avoir des origines très différentes, ce qui doit influencer la réponse apportée.", "perfect": "Je prends en compte l''information donnée par le personnel soignant sur une possible origine médicale de cette agressivité, ce qui m''incite à ne pas traiter d''emblée cette situation comme un simple trouble à l''ordre public relevant d''une réponse purement répressive.\n\nJe sollicite l''avis complémentaire du personnel médical présent avant d''arrêter ma propre appréciation de la situation, cette expertise médicale pouvant m''éclairer utilement sur la part symptomatique éventuelle de ce comportement.\n\nJe ne minimise pas pour autant le risque réel que représente ce comportement imprévisible pour les autres patients présents, cette prudence médicale ne devant pas m''empêcher de rester vigilante sur la sécurité immédiate de la salle d''attente.\n\nJe reste ouverte à ce que la réponse appropriée combine à la fois un volet de sécurisation immédiate et un volet d''orientation vers une prise en charge médicale adaptée, plutôt qu''une réponse binaire uniquement répressive ou uniquement médicale.", "points": [{"position": 1, "label": "Prendre en compte l''information sur une possible origine médicale", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : l''agressivité peut être un symptôme, pas une simple infraction.", "groups": [{"position": 1, "keywords": ["origine médicale possible", "pas simple trouble", "symptôme"]}]}, {"position": 2, "label": "Solliciter l''avis complémentaire du personnel médical avant d''arrêter son appréciation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Expertise médicale éclairant la part symptomatique du comportement.", "groups": [{"position": 1, "keywords": ["avis médical", "avant l''appréciation", "part symptomatique"]}]}, {"position": 3, "label": "Ne pas minimiser le risque pour les autres patients présents", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rester vigilante sur la sécurité malgré la prudence médicale.", "groups": [{"position": 1, "keywords": ["ne pas minimiser le risque", "sécurité de la salle", "vigilance"]}]}, {"position": 4, "label": "Envisager une réponse combinant sécurisation et orientation médicale", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Plutôt qu''une réponse binaire uniquement répressive.", "groups": [{"position": 1, "keywords": ["réponse combinée", "sécurisation et médical", "pas binaire"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment engagez-vous le contact avec cet homme compte tenu de cette possible origine médicale de son comportement ?", "hint": "L''approche verbale peut différer selon qu''on suppose une simple colère ou un état confusionnel sous-jacent.", "perfect": "J''engage un contact calme et posé, en évitant tout ton autoritaire ou provocateur qui pourrait aggraver une éventuelle confusion ou détresse sous-jacente plutôt que de la faire cesser.\n\nJe pose des questions simples pour évaluer son état de conscience et sa cohérence, ce qui peut m''aider à distinguer une colère ordinaire liée à l''attente d''un état confusionnel plus préoccupant nécessitant une prise en charge différente.\n\nJe reste attentive à ne pas le brusquer physiquement dans l''immédiat, sauf si son comportement évolue vers un danger direct et imminent pour lui-même ou pour autrui, ce qui changerait radicalement la nature de mon intervention.\n\nJe communique avec le personnel médical sur mes propres observations pendant cet échange, cette collaboration continue entre nous permettant d''affiner l''évaluation de la situation au fur et à mesure.", "points": [{"position": 1, "label": "Engager un contact calme sans ton autoritaire ou provocateur", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Éviter d''aggraver une éventuelle confusion ou détresse sous-jacente.", "groups": [{"position": 1, "keywords": ["contact calme", "sans ton autoritaire", "éviter d''aggraver"]}]}, {"position": 2, "label": "Poser des questions simples pour évaluer sa cohérence", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Distinguer une colère ordinaire d''un état confusionnel préoccupant.", "groups": [{"position": 1, "keywords": ["évaluer la cohérence", "état de conscience", "distinguer colère et confusion"]}]}, {"position": 3, "label": "Ne pas le brusquer physiquement sauf danger direct et imminent", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réserver la contrainte à un changement radical de situation.", "groups": [{"position": 1, "keywords": ["ne pas brusquer", "sauf danger imminent", "changement radical"]}]}, {"position": 4, "label": "Communiquer en continu avec le personnel médical sur ses observations", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Affiner l''évaluation de la situation au fur et à mesure.", "groups": [{"position": 1, "keywords": ["communiquer avec le médical", "affiner l''évaluation", "collaboration continue"]}]}]}, {"position": 3, "max_points": 5, "label": "Le médecin, après une brève évaluation, confirme un état confusionnel nécessitant une prise en charge médicale spécifique. Comment adaptez-vous la suite de votre intervention ?", "hint": "La confirmation médicale change la nature de la réponse à apporter, sans faire disparaître les enjeux de sécurité.", "perfect": "Je laisse le médecin orienter la prise en charge vers le soin plutôt que vers une réponse purement sécuritaire ou procédurale, cette confirmation médicale devant clairement guider la suite de mon intervention.\n\nJe reste présente pour appuyer le personnel médical si nécessaire dans la gestion pratique de cette prise en charge, notamment si une contention médicale devait être envisagée par les professionnels de santé eux-mêmes.\n\nJe ne transforme pas cet incident en simple procédure répressive maintenant que l''origine médicale est confirmée, ce qui serait inadapté à la réalité de sa situation telle qu''établie par l''expertise professionnelle.\n\nJe reste néanmoins vigilante sur la sécurité des autres patients pendant toute la durée de cette prise en charge, cette dimension sécuritaire ne disparaissant pas totalement malgré la réorientation médicale de la situation.", "points": [{"position": 1, "label": "Laisser le médecin orienter vers le soin plutôt qu''une réponse sécuritaire", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : solliciter l''avis médical avant de traiter comme un trouble.", "groups": [{"position": 1, "keywords": ["orienter vers le soin", "pas sécuritaire", "confirmation médicale"]}]}, {"position": 2, "label": "Rester présente pour appuyer le personnel médical si nécessaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Notamment si une contention médicale devait être envisagée par les professionnels.", "groups": [{"position": 1, "keywords": ["appuyer le personnel médical", "contention médicale", "si nécessaire"]}]}, {"position": 3, "label": "Ne pas transformer l''incident en procédure répressive après confirmation médicale", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Inadapté à la réalité établie par l''expertise professionnelle.", "groups": [{"position": 1, "keywords": ["pas de procédure répressive", "inadapté", "expertise professionnelle"]}]}, {"position": 4, "label": "Rester vigilante sur la sécurité des autres patients pendant la prise en charge", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "La dimension sécuritaire ne disparaît pas totalement.", "groups": [{"position": 1, "keywords": ["vigilance sécurité", "autres patients", "ne disparaît pas totalement"]}]}]}]}'::jsonb);

-- secours-appel-pour-cris-erreur-adresse — Personne ne crie ici, vous vous êtes trompés d'étage
SELECT public.fn_cp_import_case('secours-appel-pour-cris-erreur-adresse', '{"slug": "secours-appel-pour-cris-erreur-adresse", "title": "Personne ne crie ici, vous vous êtes trompés d''étage", "theme_slug": "police-secours", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 22 h 40. Vous êtes engagés dans un immeuble suite à un appel signalant des cris et une possible dispute violente à un étage précis, transmis par un voisin qui n''a pas su indiquer avec certitude l''appartement exact d''où provenaient les bruits. Arrivés à l''étage indiqué, vous sonnez à la porte correspondante : un homme âgé vous ouvre, visiblement surpris, affirmant qu''aucun cri ne provient de chez lui et qu''il regardait simplement la télévision tranquillement.\n\nRien dans son comportement ni dans l''appartement, dont il vous laisse volontiers apercevoir l''intérieur, ne corrobore le signalement initial. Il n''a lui-même rien entendu de particulier ce soir, mais confirme qu''il arrive parfois d''entendre des bruits provenant d''autres appartements de l''immeuble, sans savoir précisément lesquels.\n\nVous vous trouvez face à une information initiale visiblement imprécise ou erronée quant à la localisation exacte de l''incident signalé, sans pour autant pouvoir exclure qu''un incident réel se soit produit ailleurs dans l''immeuble.", "questions": [{"position": 1, "max_points": 5, "label": "Cette première vérification négative vous conduit-elle à considérer l''intervention comme terminée ?", "hint": "Une information imprécise sur la localisation ne signifie pas que le signalement initial était infondé.", "perfect": "Je ne considère absolument pas cette intervention comme terminée sur la seule base de cette première vérification négative, l''imprécision du signalement initial sur la localisation exacte n''invalidant en rien la réalité possible de cris entendus ailleurs dans l''immeuble.\n\nJe persévère méthodiquement en élargissant ma recherche aux étages ou appartements voisins de celui initialement indiqué, cette méthode progressive étant plus efficace qu''un abandon précoce après un seul échec de localisation.\n\nJe remercie l''homme pour sa coopération et je clarifie avec lui, avant de poursuivre, s''il a des informations même partielles sur d''où pourraient provenir les bruits qu''il évoque entendre parfois d''autres appartements.\n\nJe ne me précipite pas non plus pour frapper à toutes les portes de manière désordonnée et intrusive, en gardant une méthode progressive et respectueuse des autres occupants de l''immeuble qui n''ont probablement rien à voir avec ce signalement.", "points": [{"position": 1, "label": "Ne pas considérer l''intervention comme terminée après une seule vérification négative", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : persévérer méthodiquement au lieu de clore l''intervention.", "groups": [{"position": 1, "keywords": ["ne pas terminer", "après une vérification négative", "persévérer"]}]}, {"position": 2, "label": "Élargir méthodiquement la recherche aux étages ou appartements voisins", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Méthode progressive plus efficace qu''un abandon précoce.", "groups": [{"position": 1, "keywords": ["élargir la recherche", "méthodique", "pas d''abandon précoce"]}]}, {"position": 3, "label": "Clarifier avec l''homme s''il a des informations même partielles", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Recueillir tout indice utile avant de poursuivre.", "groups": [{"position": 1, "keywords": ["clarifier avec lui", "informations partielles", "indice utile"]}]}, {"position": 4, "label": "Ne pas frapper à toutes les portes de manière désordonnée et intrusive", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Méthode progressive et respectueuse des autres occupants.", "groups": [{"position": 1, "keywords": ["pas désordonné", "respectueux", "méthode progressive"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment organisez-vous méthodiquement la poursuite de vos recherches dans l''immeuble ?", "hint": "Une méthode systématique augmente les chances de localiser l''origine réelle sans perdre de temps ni multiplier les dérangements inutiles.", "perfect": "Je procède étage par étage à partir du point initialement signalé, en élargissant progressivement le rayon de recherche plutôt que de sauter aléatoirement d''un endroit à l''autre de l''immeuble sans méthode.\n\nJe reste attentive à tout signe sonore ou visuel qui pourrait m''orienter plus précisément pendant cette progression, comme une porte entrouverte, une lumière particulière, ou tout indice qui n''aurait pas été perceptible depuis l''extérieur.\n\nJe sollicite si possible l''aide du voisin ayant initialement appelé, s''il est disponible et peut préciser davantage sa perception initiale des bruits, ce qui pourrait affiner ma zone de recherche.\n\nJe garde une trace de chaque porte déjà vérifiée négativement, ce qui évite de perdre du temps à revérifier les mêmes endroits et me permet de rester méthodique dans une recherche qui peut prendre du temps.", "points": [{"position": 1, "label": "Procéder étage par étage en élargissant progressivement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Méthode systématique plutôt qu''aléatoire.", "groups": [{"position": 1, "keywords": ["étage par étage", "élargir progressivement", "méthode systématique"]}]}, {"position": 2, "label": "Rester attentive à tout signe sonore ou visuel orientant la recherche", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Indices non perceptibles depuis l''extérieur initialement.", "groups": [{"position": 1, "keywords": ["signes sonores ou visuels", "orienter la recherche", "indices"]}]}, {"position": 3, "label": "Solliciter le voisin ayant appelé pour préciser sa perception initiale", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Affiner la zone de recherche avec des précisions complémentaires.", "groups": [{"position": 1, "keywords": ["solliciter le voisin", "préciser la perception", "affiner la zone"]}]}, {"position": 4, "label": "Garder une trace des portes déjà vérifiées négativement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Éviter de perdre du temps à revérifier les mêmes endroits.", "groups": [{"position": 1, "keywords": ["trace des vérifications", "éviter de revérifier", "rester méthodique"]}]}]}, {"position": 3, "max_points": 5, "label": "Vous finissez par localiser l''appartement d''origine, deux étages plus bas, où un couple confirme une dispute désormais terminée sans gravité. Comment concluez-vous cette intervention prolongée ?", "hint": "Le temps investi dans cette recherche méthodique se justifie par le résultat obtenu, même modeste.", "perfect": "Je recueille les explications du couple sur cette dispute, en vérifiant qu''elle s''est effectivement terminée sans conséquence grave et qu''aucune violence physique n''est à déplorer au-delà des éclats de voix qui ont été entendus.\n\nJe ne considère pas le temps passé à cette recherche méthodique comme disproportionné par rapport au résultat obtenu, cette persévérance ayant été nécessaire pour localiser correctement l''origine réelle du signalement initial imprécis.\n\nJe consigne avec précision le décalage entre la localisation initiale signalée et l''endroit réel de l''incident, ce qui pourra être utile pour améliorer la précision des futurs signalements similaires dans cet immeuble.\n\nJe reste attentive aux signes qui pourraient indiquer que cette dispute n''est pas isolée ou pourrait se reproduire, sans pour autant sur-interpréter une situation qui semble, à ce stade, être un différend ponctuel résolu.", "points": [{"position": 1, "label": "Recueillir les explications en vérifiant l''absence de violence physique", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "S''assurer que la dispute s''est terminée sans conséquence grave.", "groups": [{"position": 1, "keywords": ["recueillir les explications", "vérifier l''absence de violence", "sans conséquence grave"]}]}, {"position": 2, "label": "Ne pas considérer le temps passé comme disproportionné", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "La persévérance était nécessaire pour localiser correctement l''origine.", "groups": [{"position": 1, "keywords": ["pas disproportionné", "persévérance nécessaire", "localisation correcte"]}]}, {"position": 3, "label": "Consigner le décalage entre localisation initiale et réelle", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Utile pour améliorer la précision de futurs signalements.", "groups": [{"position": 1, "keywords": ["consigner le décalage", "amélioration future", "précision des signalements"]}]}, {"position": 4, "label": "Rester attentive sans sur-interpréter un différend ponctuel résolu", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance mesurée face à une situation qui semble résolue.", "groups": [{"position": 1, "keywords": ["sans sur-interpréter", "différend ponctuel", "vigilance mesurée"]}]}]}]}'::jsonb);

-- secours-effondrement-partiel-batiment — Un balcon s'est détaché, la façade se fissure
SELECT public.fn_cp_import_case('secours-effondrement-partiel-batiment', '{"slug": "secours-effondrement-partiel-batiment", "title": "Un balcon s''est détaché, la façade se fissure", "theme_slug": "police-secours", "difficulty": "expert", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 35, "situation_text": "Il est 6 h 45. Vous êtes la première patrouille sur place devant un immeuble ancien de six étages où un balcon vient de se détacher et de s''effondrer sur le trottoir, heureusement désert à cette heure. Vous constatez que la façade présente des fissures visibles et évolutives sur plusieurs étages, laissant craindre un risque de sur-effondrement plus large de la structure.\n\nDes habitants de l''immeuble, réveillés par le bruit, commencent à sortir sur le pas de leur porte ou à leurs fenêtres, certains ne réalisant pas encore la gravité de la situation structurelle du bâtiment. Le nombre exact de personnes présentes à l''intérieur à cette heure matinale n''est pas connu avec certitude.\n\nLes pompiers ont été alertés mais ne sont pas encore sur place, et vous ne disposez d''aucune expertise structurelle pour évaluer précisément le risque de sur-effondrement, seule l''évidence visuelle des fissures et du balcon tombé vous alertant sur la gravité potentielle de la situation.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre priorité absolue face à ce risque de sur-effondrement dont vous ne pouvez pas évaluer précisément la gravité ?", "hint": "L''incertitude sur l''ampleur exacte du risque structurel doit conduire à la prudence maximale plutôt qu''à une évaluation optimiste par défaut.", "perfect": "Ma priorité absolue est l''établissement d''un périmètre de sécurité large autour du bâtiment, l''incertitude totale sur l''ampleur du risque structurel imposant une prudence maximale plutôt qu''une évaluation optimiste que je ne suis pas qualifiée à faire.\n\nJe fais évacuer sans délai les riverains et passants qui pourraient se trouver à proximité immédiate de la façade fissurée, ce risque de chute de matériaux ou de sur-effondrement étant prioritaire sur toute autre considération à cet instant.\n\nJe communique en urgence absolue la gravité de la situation à mon central, en sollicitant sans délai les pompiers et tout service d''expertise structurelle compétent, cette situation dépassant très largement ce qu''une intervention policière classique peut évaluer seule.\n\nJe ne m''engage à aucun moment dans le bâtiment moi-même pour évaluer l''ampleur des dégâts ou porter secours à d''éventuelles victimes, cette action dépassant totalement mes compétences et pouvant m''exposer à un risque mortel dans une structure dont la stabilité n''est plus garantie.", "points": [{"position": 1, "label": "Établir un périmètre de sécurité large par prudence maximale", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : périmètre large et évacuation avant toute recherche de victimes.", "groups": [{"position": 1, "keywords": ["périmètre large", "prudence maximale", "priorité absolue"]}]}, {"position": 2, "label": "Faire évacuer sans délai riverains et passants proches de la façade", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Risque de chute de matériaux ou de sur-effondrement prioritaire.", "groups": [{"position": 1, "keywords": ["évacuer sans délai", "riverains et passants", "façade fissurée"]}]}, {"position": 3, "label": "Communiquer en urgence absolue et solliciter les pompiers et l''expertise structurelle", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Situation dépassant largement l''évaluation policière classique.", "groups": [{"position": 1, "keywords": ["urgence absolue", "pompiers et expertise", "dépasse la compétence"]}]}, {"position": 4, "label": "Ne pas s''engager soi-même dans le bâtiment pour évaluer ou secourir", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Risque mortel dans une structure dont la stabilité n''est plus garantie.", "groups": [{"position": 1, "keywords": ["ne pas s''engager", "risque mortel", "stabilité non garantie"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous les habitants qui sortent sur leur balcon ou à leurs fenêtres sans réaliser la gravité de la situation ?", "hint": "Certains habitants pourraient rester exposés sans comprendre le danger réel de leur propre position.", "perfect": "J''interpelle sans délai les habitants visibles à leurs fenêtres ou balcons pour leur demander de rentrer immédiatement à l''intérieur et de s''éloigner des façades fissurées, ce risque n''étant pas nécessairement perçu par eux depuis l''intérieur de leur logement.\n\nJe communique clairement et fermement la gravité de la situation, sans dramatiser excessivement au point de provoquer une panique incontrôlée, mais en étant suffisamment explicite pour qu''ils comprennent l''urgence de s''éloigner des zones à risque.\n\nJe recherche activement à évaluer, avec les moyens dont je dispose, si une évacuation complète de l''immeuble doit être envisagée en urgence, cette décision dépassant probablement ma seule compétence mais nécessitant une action immédiate en attendant les services compétents.\n\nJe reste attentive à ce que ma propre position et celle de mes collègues ne nous expose pas nous-mêmes inutilement à proximité immédiate de la façade instable pendant cette phase de gestion des habitants.", "points": [{"position": 1, "label": "Interpeller les habitants aux fenêtres pour qu''ils rentrent et s''éloignent des façades", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Risque non nécessairement perçu depuis l''intérieur du logement.", "groups": [{"position": 1, "keywords": ["interpeller les habitants", "rentrer et s''éloigner", "risque non perçu"]}]}, {"position": 2, "label": "Communiquer la gravité fermement sans provoquer de panique incontrôlée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Explicite sur l''urgence sans dramatisation excessive.", "groups": [{"position": 1, "keywords": ["fermement", "sans panique incontrôlée", "explicite sur l''urgence"]}]}, {"position": 3, "label": "Évaluer si une évacuation complète de l''immeuble doit être envisagée en urgence", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Action immédiate en attendant les services compétents pour la décision finale.", "groups": [{"position": 1, "keywords": ["évacuation complète", "en urgence", "en attendant les compétents"]}]}, {"position": 4, "label": "Rester attentif à ne pas s''exposer soi-même près de la façade instable", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sécurité personnelle pendant la gestion des habitants.", "groups": [{"position": 1, "keywords": ["ne pas s''exposer soi-même", "sécurité personnelle", "façade instable"]}]}]}, {"position": 3, "max_points": 5, "label": "Les pompiers et les services d''expertise arrivent enfin. Quel rôle jouez-vous à partir de ce moment pour cet événement de grande ampleur ?", "hint": "Un événement multi-services nécessite une coordination claire des rôles respectifs, sans concurrence ni flou.", "perfect": "Je transmets immédiatement aux services arrivants l''ensemble des informations recueillies depuis mon arrivée : évolution des fissures observée, nombre approximatif d''habitants évacués ou restants, mesures déjà prises pour sécuriser le périmètre.\n\nJe me positionne clairement au service de la coordination multi-services qui se met en place, en acceptant que la direction des opérations revienne désormais aux services les plus compétents pour ce type d''événement structurel de grande ampleur.\n\nJe continue à assurer la gestion du périmètre de sécurité et du public, cette mission restant pleinement de ma compétence et libérant les services spécialisés pour se concentrer sur l''expertise technique et le sauvetage éventuel.\n\nJe reste disponible pour toute mission complémentaire qui me serait confiée dans le cadre de ce dispositif coordonné, sans chercher à conserver une position de premier plan qui ne serait plus justifiée une fois les services compétents mobilisés.", "points": [{"position": 1, "label": "Transmettre immédiatement toutes les informations recueillies aux services arrivants", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Évolution des fissures, habitants évacués, mesures déjà prises.", "groups": [{"position": 1, "keywords": ["transmettre les informations", "services arrivants", "mesures déjà prises"]}]}, {"position": 2, "label": "Se positionner au service de la coordination multi-services", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Accepter que la direction revienne aux services les plus compétents.", "groups": [{"position": 1, "keywords": ["coordination multi-services", "direction aux compétents", "accepter le transfert"]}]}, {"position": 3, "label": "Continuer à assurer la gestion du périmètre et du public", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Libérer les services spécialisés pour l''expertise technique et le sauvetage.", "groups": [{"position": 1, "keywords": ["gestion du périmètre", "libérer les spécialisés", "expertise technique"]}]}, {"position": 4, "label": "Rester disponible pour des missions complémentaires sans chercher le premier plan", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Position adaptée une fois les services compétents mobilisés.", "groups": [{"position": 1, "keywords": ["missions complémentaires", "pas de premier plan", "services mobilisés"]}]}]}]}'::jsonb);

COMMIT;
